/** `styles.scrollbarWidth`. The whole grammar: Chromium 151 rejects `thick` and a `<length>` outright, measured — MDN's scrollbars guide is wrong about both. `NONE` hides the bar without disabling the wheel, which is exactly what the property means. */
export const ScrollbarWidth = {
  AUTO: 0,
  THIN: 1,
  NONE: 2,
} as const;
export type ScrollbarWidth = (typeof ScrollbarWidth)[keyof typeof ScrollbarWidth];

/** `styles.appearance`. An *effect*, not the specified value — `<compat-auto>` keywords all collapse to `AUTO` here, which is what the spec says they do and what makes storing nine more variants pointless. `BASE_SELECT` is the opt-in that makes a `<select>` and its `::picker(select)` fully styleable; it is the one value that changes what gets drawn rather than merely whether. Measured against Chromium 151 — see BROWSER-FACTS.md. */
export const Appearance = {
  NONE: 0,
  AUTO: 1,
  BASE_SELECT: 2,
} as const;
export type Appearance = (typeof Appearance)[keyof typeof Appearance];

